// Kizzasi WASM Web Worker
// Handles signal quantization/reconstruction off the main thread.

let wasmModule = null;

self.addEventListener("message", async function (e) {
  const msg = e.data;

  if (msg.type === "init") {
    try {
      // Dynamic import of the WASM glue generated by wasm-pack
      const wasm = await import("./pkg/kizzasi_tokenizer.js");
      await wasm.default();
      wasmModule = wasm;
      self.postMessage({ type: "ready" });
    } catch (err) {
      self.postMessage({ type: "error", message: "Failed to load WASM: " + (err.message || String(err)) });
    }
    return;
  }

  if (!wasmModule) {
    self.postMessage({ type: "error", message: "WASM module not initialized. Send 'init' first." });
    return;
  }

  if (msg.type === "quantize") {
    handleLinearQuantize(msg.signal, msg.bits);
  } else if (msg.type === "mulaw") {
    handleMuLaw(msg.signal, msg.bits);
  } else {
    self.postMessage({ type: "error", message: "Unknown message type: " + msg.type });
  }
});

/**
 * Linear quantization: encode each sample then decode to get reconstructed signal.
 */
function handleLinearQuantize(signal, bits) {
  try {
    // Determine signal range for the linear quantizer
    let min = Infinity;
    let max = -Infinity;
    for (let i = 0; i < signal.length; i++) {
      if (signal[i] < min) min = signal[i];
      if (signal[i] > max) max = signal[i];
    }
    // Add small epsilon to avoid min === max
    if (max - min < 1e-9) {
      max = min + 1.0;
    }

    const quantizer = new wasmModule.WasmLinearQuantizer(min, max, bits);
    const original = new Float32Array(signal.length);
    const reconstructed = new Float32Array(signal.length);

    for (let i = 0; i < signal.length; i++) {
      original[i] = signal[i];
      const code = quantizer.encode(signal[i]);
      reconstructed[i] = quantizer.decode(code);
    }

    const metrics = computeMetrics(original, reconstructed, bits);

    self.postMessage({
      type: "result",
      original: original,
      reconstructed: reconstructed,
      snr: metrics.snr,
      mse: metrics.mse,
      compression_ratio: metrics.compression_ratio,
    });
  } catch (err) {
    self.postMessage({ type: "error", message: "Linear quantize error: " + (err.message || String(err)) });
  }
}

/**
 * Mu-law quantization: encode each sample then decode to get reconstructed signal.
 */
function handleMuLaw(signal, bits) {
  try {
    const codec = new wasmModule.WasmMuLawCodec(bits);
    const original = new Float32Array(signal.length);
    const reconstructed = new Float32Array(signal.length);

    for (let i = 0; i < signal.length; i++) {
      original[i] = signal[i];
      const code = codec.encode(signal[i]);
      reconstructed[i] = codec.decode(code);
    }

    const metrics = computeMetrics(original, reconstructed, bits);

    self.postMessage({
      type: "result",
      original: original,
      reconstructed: reconstructed,
      snr: metrics.snr,
      mse: metrics.mse,
      compression_ratio: metrics.compression_ratio,
    });
  } catch (err) {
    self.postMessage({ type: "error", message: "Mu-law error: " + (err.message || String(err)) });
  }
}

/**
 * Compute quality metrics for the quantization result.
 *
 * SNR  = 10 * log10(signal_power / noise_power)
 * MSE  = mean((original - reconstructed)^2)
 * Compression ratio = 32 / bits  (original is f32 = 32-bit)
 */
function computeMetrics(original, reconstructed, bits) {
  const n = original.length;
  let signalPower = 0;
  let noisePower = 0;
  let mseSum = 0;

  for (let i = 0; i < n; i++) {
    const diff = original[i] - reconstructed[i];
    signalPower += original[i] * original[i];
    noisePower += diff * diff;
    mseSum += diff * diff;
  }

  signalPower /= n;
  noisePower /= n;
  const mse = mseSum / n;

  let snr;
  if (noisePower < 1e-30) {
    snr = Infinity;
  } else {
    snr = 10 * Math.log10(signalPower / noisePower);
  }

  const compression_ratio = 32 / bits;

  return { snr: snr, mse: mse, compression_ratio: compression_ratio };
}
